class Solution:
    def canAliceWin(self, a: List[str], b: List[List[str]]) -> bool:
        def next_word(last_char: str, words: List[str]) -> str:
            # Find the smallest word in `words` that starts with the next letter after `last_char`
            # or the same letter and is lexicographically greater than the last played word.
            target = chr(ord(last_char) + 1)
            i = 0
            while i < len(words):
                if words[i][0] == last_char:
                    i += 1
                elif words[i][0] == target:
                    return words[i]
                else:
                    break
            return None

        alice_turn = True
        a_index = 0
        b_index = 0

        # Alice plays her first word
        current = a[a_index]
        a_index += 1

        while True:
            if alice_turn:
                # Alice's turn
                word = next_word(current[0], a[a_index:])
                if word is None:
                    return False  # Alice cannot play
                current = word
                a_index += (a[a_index:].index(word) + 1)
            else:
                # Bob's turn
                word = next_word(current[0], b[b_index:])
                if word is None:
                    return True  # Bob cannot play, Alice wins
                current = word
                b_index += (b[b_index:].index(word) + 1)

            alice_turn = not alice_turn
```

