class Solution:
    def minOperations(self, nums: List[int]) -> int:
        calls = 0
        max_bit = 0

        for num in nums:
            bit = 0
            n = num
            while n > 0:
                if n & 1:
                    calls += 1
                n >>= 1
                bit += 1
            max_bit = max(max_bit, bit)

        if max_bit > 0:
            calls += (max_bit - 1)

        return calls

