class Solution:
    def strobogrammaticInRange(self, low: str, high: str) -> int:
        pairs = [('0', '0'), ('1', '1'), ('6', '9'), ('8', '8'), ('9', '6')]

        def build(n, total):
            if n == 0:
                return [""]
            if n == 1:
                return ["0", "1", "8"]

            prev = build(n - 2, total)
            res = []
            for p in prev:
                for a, b in pairs:
                    # Skip leading zero unless the number is exactly "0" (handled by n==total check)
                    if n == total and a == '0' and n > 1:
                        continue
                    res.append(a + p + b)
            return res

        count = 0
        len_low = len(low)
        len_high = len(high)

        for length in range(len_low, len_high + 1):
            for num in build(length, length):
                # Check bounds based on length
                if len(num) == len_low and num < low:
                    continue
                if len(num) == len_high and num > high:
                    continue
                count += 1

        return count

