class Solution:
    def strobogrammaticInRange(self, low: str, high: str) -> int:
        pairs = [('0', '0'), ('1', '1'), ('6', '9'), ('8', '8'), ('9', '6')]

        def build(n, total):
            if n == 0:
                return [""]
            if n == 1:
                return ["0", "1", "8"]

            prev = build(n - 2, total)
            res = []
            for p in prev:
                for a, b in pairs:
                    if n == total and p == "" and a == '0':
                        continue  # skip leading zero
                    res.append(a + p + b)
            return res

        count = 0
        for length in range(len(low), len(high) + 1):
            for num in build(length, length):
                if (len(num) == len(low) and num < low) or (len(num) == len(high) and num > high):
                    continue
                count += 1
        return count

