class Solution:
    def makeConnected(self, n: int, connections: List[List[int]]) -> int:
        # Not enough cables to connect all computers (at least n - 1 edges needed)
        if len(connections) < n - 1:
            return -1

        parent = list(range(n))

        def find(x):
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        def union(x, y):
            px, py = find(x), find(y)
            if px == py:
                return False  # Already connected
            parent[px] = py
            return True

        components = n
        for a, b in connections:
            if union(a, b):
                components -= 1

        # To connect all components, we need (components - 1) operations
        return components - 1
```

