class Solution:
    def makeConnected(self, n: int, connections: List[List[int]]) -> int:
        if len(connections) < n - 1:
            return -1

        parent = list(range(n))

        def find(x):
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        def union(x, y):
            px, py = find(x), find(y)
            if px == py:
                return False
            parent[px] = py
            return True

        redundant_cables = 0
        for a, b in connections:
            if not union(a, b):
                redundant_cables += 1

        components = n
        # Re-count components by checking how many unique roots exist after processing all unions
        # Actually, we can just track the number of successful unions.
        # Initial components = n. Each successful union reduces component count by 1.
        # But we need to know how many components are left.
        # Let's re-calculate components properly or track it during union.

        # Reset approach: Track components correctly.
        parent = list(range(n))
        def find(x):
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        def union(x, y):
            px, py = find(x), find(y)
            if px == py:
                return False
            parent[px] = py
            return True

        components = n
        extra_edges = 0
        for a, b in connections:
            if not union(a, b):
                extra_edges += 1
            else:
                components -= 1

        needed = components - 1
        if extra_edges >= needed:
            return needed
        return -1

