class Solution:
    def minimizedMaximum(self, n: int, quantities: List[int]) -> int:
        # Helper function to check if it's possible to distribute all products with max 'mid'
        def can_distribute(max_per_store):
            required_stores = 0
            for q in quantities:
                required_stores += (q + max_per_store - 1) // max_per_store  # ceil division
                if required_stores > n:
                    return False
            return True

        # Binary search for the minimum possible maximum number of products per store
        left, right = 1, max(quantities)
        while left < right:
            mid = (left + right) // 2
            if can_distribute(mid):
                right = mid
            else:
                left = mid + 1
        return left
