class Solution:
    def sumPrefixScores(self, words: List[str]) -> List[int]:
        from collections import defaultdict

        prefix_count = defaultdict(int)

        # First pass: count how many times each prefix appears across all words
        for word in words:
            for i in range(1, len(word) + 1):
                prefix = word[:i]
                prefix_count[prefix] += 1

        # Second pass: for each word, sum the counts of all its prefixes
        result = []
        for word in words:
            total = 0
            for i in range(1, len(word) + 1):
                prefix = word[:i]
                total += prefix_count[prefix]
            result.append(total)

        return result

