class Solution:
    def validSquare(self, p1: List[int], p2: List[int], p3: List[int], p4: List[int]) -> bool:
        from collections import Counter

        # Function to calculate squared distance between two points
        def dist_squared(a, b):
            return (a[0] - b[0])**2 + (a[1] - b[1])**2

        points = [p1, p2, p3, p4]
        distances = []

        # Compute all pairwise squared distances
        for i in range(4):
            for j in range(i+1, 4):
                distances.append(dist_squared(points[i], points[j]))

        # A square has 6 distances: 4 equal sides and 2 equal diagonals
        count = Counter(distances)

        # Must have exactly 2 distinct distances
        if len(count) != 2:
            return False

        side, diag = sorted(count.keys())

        # Check that there are 4 sides and 2 diagonals
        # Also ensure side > 0 (points are not coincident)
        if count[side] == 4 and count[diag] == 2 and diag == 2 * side and side > 0:
            return True
        return False

class Solution:
    def minElements(self, nums: List[int], limit: int, goal: int) -> int:
        current_sum = sum(nums)
        difference = abs(goal - current_sum)
        return (difference + limit - 1) // limit

