class Solution:
    def canConvert(self, str1: str, str2: str) -> bool:
        if str1 == str2:
            return True

        # We need a mapping from characters in str1 to characters in str2
        conversion_map = {}

        for c1, c2 in zip(str1, str2):
            if conversion_map.get(c1, c2) != c2:
                # If the character c1 is already mapped to a different character,
                # conversion is not possible
                return False
            conversion_map[c1] = c2

        # To perform all conversions, we must have less than 26 unique characters in str2
        # because one character is needed as an intermediate to convert others
        return len(set(str2)) < 26
```

