class Solution:
    def minimumTimeToInitialState(self, word: str, k: int) -> int:
        n = len(word)
        time = 0

        # At each step, we remove first k characters and add any k characters.
        # After t steps, the prefix of length k*t must match the suffix of length k*t for the word to return to original state.

        for t in range(0, n // k + 1):
            removed_chars = t * k
            if removed_chars > n:
                break
            if word[:n - removed_chars] == word[removed_chars:]:
                if t > 0:
                    return t
        return n // k + 1
```

final_answer:
class Solution:
    def minimumTimeToInitialState(self, word: str, k: int) -> int:
        n = len(word)

        # We need to find the smallest t > 0 such that after t operations,
        # the remaining suffix of length (n - t*k) matches the prefix of the original word.
        # If we remove t*k characters from the front, the remaining part is word[t*k:].
        # For the string to be restorable to its original form by appending arbitrary characters,
        # the suffix word[t*k:] must match the prefix word[:n-t*k].

        for t in range(1, (n + k - 1) // k + 1):
            if t * k >= n:
                return t

            if word[t*k:] == word[:n - t*k]:
                return t

        return (n + k - 1) // k

