class Solution:
    def minimumTimeToInitialState(self, word: str, k: int) -> int:
        n = len(word)
        if k >= n:
            return 1

        # We need to find the smallest t such that after removing t*k characters from the front,
        # the remaining prefix of length (n - t*k) matches the suffix of the original string.
        # If we can't match any prefix, we need enough steps to remove the entire string,
        # which takes ceil(n/k) steps.

        max_t = (n + k - 1) // k  # Equivalent to ceil(n/k)

        for t in range(1, max_t + 1):
            removed_chars = t * k
            if removed_chars >= n:
                return t

            # Check if the remaining part of the string (suffix starting at index removed_chars)
            # matches the beginning of the original string (prefix of same length).
            if word[removed_chars:] == word[:n - removed_chars]:
                return t

        return max_t

