class Solution:
    def minimumTimeToInitialState(self, word: str, k: int) -> int:
        n = len(word)

        # If k is larger than or equal to the length of the word, 
        # we can just remove the whole word in 1 step and replace it with anything.
        if k >= n:
            return 1

        # We need to find the smallest t > 0 such that after removing t*k characters from the front,
        # the remaining prefix of the original word matches the suffix of the original word starting at index t*k.
        # Specifically, word[:n - t*k] must equal word[t*k:].
        # This ensures that by adding arbitrary characters (which will overwrite the removed part conceptually),
        # we can reconstruct the original string. The condition is that the "overlap" part must match.

        for t in range(1, n // k + 2):
            removed_chars = t * k
            if removed_chars >= n:
                return t

            # Check if the remaining suffix of the original word (starting at removed_chars)
            # matches the prefix of the original word of the same length.
            # Length of overlap is n - removed_chars.
            if word[removed_chars:] == word[:n - removed_chars]:
                return t

        return n // k + 1

