class Solution:
    def findColumnWidth(self, grid: List[List[int]]) -> List[int]:
        ans = []
        for col in zip(*grid):
            max_width = 0
            for num in col:
                # Length of the number as a string accounts for '-' and digits
                length = len(str(num))
                if length > max_width:
                    max_width = length
            ans.append(max_width)
        return ans
```

