class Solution:
    def minInsertions(self, s: str) -> int:
        insertions = 0
        balance = 0

        for char in s:
            if char == '(':
                # If we have an odd balance (one ')'), we need to add one ')' to make it even
                if balance % 2 != 0:
                    insertions += 1
                    balance -= 1
                balance += 2
            else:
                balance -= 1
                # If balance becomes negative, we need to add a '('
                if balance < 0:
                    insertions += 1
                    balance += 2

        return insertions + balance

