from typing import List

class Solution:
    def minimumAddedInteger(self, nums1: List[int], nums2: List[int]) -> int:
        nums1.sort()
        nums2.sort()

        # Try all combinations of removing two elements from nums1
        min_x = float('inf')
        for i in range(len(nums1)):
            for j in range(i + 1, len(nums1)):
                modified = [nums1[k] for k in range(len(nums1)) if k != i and k != j]
                x = nums2[0] - modified[0]
                valid = True
                for a, b in zip(modified, nums2):
                    if a + x != b:
                        valid = False
                        break
                if valid:
                    min_x = min(min_x, x)
        return min_x
```

