class Solution:
    def kConcatenationMaxSum(self, arr: List[int], k: int) -> int:
        MOD = 10**9 + 7

        def max_subarray_sum(nums):
            max_sum = 0
            current_sum = 0
            for num in nums:
                current_sum = max(num, current_sum + num)
                max_sum = max(max_sum, current_sum)
            return max_sum

        total_sum = sum(arr)
        double_arr = arr * 2
        max_one = max_subarray_sum(arr)
        max_two = max_subarray_sum(double_arr)

        if k == 1:
            return max_one % MOD
        elif total_sum <= 0:
            return max_two % MOD
        else:
            return (max_two + (k - 2) * total_sum) % MOD
