class Solution:
    def reconstructMatrix(self, upper: int, lower: int, colsum: List[int]) -> List[List[int]]:
        n = len(colsum)
        upper_row = [0] * n
        lower_row = [0] * n

        for i in range(n):
            if colsum[i] == 2:
                upper_row[i] = 1
                lower_row[i] = 1
                upper -= 1
                lower -= 1
            elif colsum[i] == 1:
                # Placeholder for columns with sum 1
                pass
            else:
                # colsum[i] == 0, nothing to do
                pass

        if upper < 0 or lower < 0:
            return []

        for i in range(n):
            if colsum[i] == 1:
                if upper > 0:
                    upper_row[i] = 1
                    upper -= 1
                elif lower > 0:
                    lower_row[i] = 1
                    lower -= 1
                else:
                    return []

        if upper != 0 or lower != 0:
            return []

        return [upper_row, lower_row]
