class Solution:
    def reconstructMatrix(self, upper: int, lower: int, colsum: List[int]) -> List[List[int]]:
        n = len(colsum)
        upper_row = [0] * n
        lower_row = [0] * n

        # First pass: handle columns with sum 2
        for i in range(n):
            if colsum[i] == 2:
                upper_row[i] = 1
                lower_row[i] = 1
                upper -= 1
                lower -= 1

        # Check if we went over the limits
        if upper < 0 or lower < 0:
            return []

        # Second pass: handle columns with sum 1
        for i in range(n):
            if colsum[i] == 1:
                if upper > 0:
                    upper_row[i] = 1
                    upper -= 1
                elif lower > 0:
                    lower_row[i] = 1
                    lower -= 1
                else:
                    # Neither row can take this 1
                    return []

        # Final check: both sums must be exactly 0
        if upper != 0 or lower != 0:
            return []

        return [upper_row, lower_row]

