class Solution:
    def minimumAddedCoins(self, coins: List[int], target: int) -> int:
        coins.sort()
        res = 0
        current_max = 0
        i = 0

        while current_max < target:
            if i < len(coins) and coins[i] <= current_max + 1:
                current_max += coins[i]
                i += 1
            else:
                # Need to add a coin of value current_max + 1
                current_max += current_max + 1
                res += 1

        return res

class Solution:
    def minimumCost(self, n: int, connections: List[List[int]]) -> int:
        # Union-Find (Disjoint Set Union) data structure
        parent = list(range(n + 1))  # cities are labeled from 1 to n

        def find(x):
            if parent[x] != x:
                parent[x] = find(parent[x])  # path compression
            return parent[x]

        def union(x, y):
            rootX = find(x)
            rootY = find(y)
            if rootX == rootY:
                return False  # already connected
            parent[rootY] = rootX  # merge
            return True

        # Sort connections by cost
        connections.sort(key=lambda x: x[2])

        total_cost = 0
        edges_used = 0

        for u, v, cost in connections:
            if union(u, v):
                total_cost += cost
                edges_used += 1
                if edges_used == n - 1:  # MST has exactly n-1 edges
                    break

        # Check if all cities are connected
        root = find(1)
        for i in range(2, n + 1):
            if find(i) != root:
                return -1

        return total_cost

from typing import List
from collections import deque

class Solution:
    def findMaxValueOfEquation(self, points: List[List[int]], k: int) -> int:
        # Use a deque to maintain potential candidates for maximum (y - x)
        q = deque()
        max_value = float('-inf')

        for xj, yj in points:
            # Remove elements from the front of the deque that are too far away in x
            while q and q[0][1] < xj - k:
                q.popleft()

            if q:
                # The best candidate is at the front of the deque
                xi, _, yi_minus_xi = q[0]
                max_value = max(max_value, yi_minus_xi + yj + (xj - xi))

            # Maintain the deque in decreasing order of (y - x)
            while q and q[-1][2] <= (yj - xj):
                q.pop()

            q.append([xj, xj + k, yj - xj])

        return max_value

