class Solution:
    def hasPath(self, maze: List[List[int]], start: List[int], destination: List[int]) -> bool:
        from collections import deque

        m, n = len(maze), len(maze[0])
        visited = [[False] * n for _ in range(m)]
        queue = deque()
        queue.append((start[0], start[1]))
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

        while queue:
            x, y = queue.popleft()

            if [x, y] == destination:
                return True

            if visited[x][y]:
                continue
            visited[x][y] = True

            for dx, dy in directions:
                nx, ny = x, y
                # Roll the ball until it hits a wall or boundary
                while 0 <= nx + dx < m and 0 <= ny + dy < n and maze[nx + dx][ny + dy] == 0:
                    nx += dx
                    ny += dy

                # Only add to queue if not visited. 
                # Note: We must check visited before adding to avoid redundant processing, 
                # but we also need to ensure we don't skip checking the destination if it's reachable via this path.
                # However, since we check for destination immediately after popping, 
                // and we mark visited upon popping, the logic holds.
                // But wait: The standard BFS approach marks visited when ENQUEUING to prevent duplicates in queue.
                // If we mark when DEQUEUING, we might add the same node multiple times.
                // Let's correct the logic to mark visited when ENQUEUING for efficiency, 
                // OR keep it as is but ensure we handle the start node correctly.
                // Actually, the provided code marks visited on pop. This can lead to duplicate entries in the queue.
                // A better practice is to mark visited when pushing to queue, EXCEPT for the start node which is already pushed.

                if not visited[nx][ny]:
                    visited[nx][ny] = True
                    queue.append((nx, ny))

        return False

