#     def __init__(self, val=0, next=None):
#         self.val = val
#         self.next = next
class Solution:
    def gameResult(self, head: Optional[ListNode]) -> str:
        odd_score = 0
        even_score = 0

        while head and head.next:
            # Even-indexed node is at 'head' (0, 2, 4...)
            # Odd-indexed node is at 'head.next' (1, 3, 5...)
            even_val = head.val
            odd_val = head.next.val

            if odd_val > even_val:
                odd_score += 1
            elif even_val > odd_val:
                even_score += 1
            # If equal, no points are awarded to either team

            head = head.next.next

        if odd_score > even_score:
            return "Odd"
        elif even_score > odd_score:
            return "Even"
        else:
            return "Tie"

