class Solution:
    def maximumCost(self, n: int, highways: List[List[int]], k: int) -> int:
        from collections import defaultdict
        import itertools

        # Build adjacency list
        graph = defaultdict(list)
        for city1, city2, toll in highways:
            graph[city1].append((city2, toll))
            graph[city2].append((city1, toll))

        max_cost = -1

        # Try all permutations of cities of length k+1 (since we cross k highways)
        for perm in itertools.permutations(range(n), k + 1):
            visited = set(perm)
            if len(visited) != k + 1:
                continue  # Skip if there are duplicate cities (shouldn't happen with permutations)

            total_cost = 0
            valid = True
            for i in range(k):
                a, b = perm[i], perm[i + 1]
                found = False
                for neighbor, cost in graph[a]:
                    if neighbor == b:
                        total_cost += cost
                        found = True
                        break
                if not found:
                    valid = False
                    break
            if valid:
                max_cost = max(max_cost, total_cost)

        return max_cost
```

final_answer:
class Solution:
    def maximumCost(self, n: int, highways: List[List[int]], k: int) -> int:
        from collections import defaultdict

        # Build adjacency list
        graph = defaultdict(list)
        for city1, city2, toll in highways:
            graph[city1].append((city2, toll))
            graph[city2].append((city1, toll))

        max_cost = -1

        # Use DFS to explore all paths of length k (visiting k+1 unique cities)
        # Since n can be up to 50 and k up to 49, we need an efficient backtracking approach.
        # itertools.permutations is O(n!) which is too slow for n=50.

        def dfs(current_city, visited, depth, current_cost):
            nonlocal max_cost
            if depth == k:
                max_cost = max(max_cost, current_cost)
                return

            for neighbor, toll in graph[current_city]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    dfs(neighbor, visited, depth + 1, current_cost + toll)
                    visited.remove(neighbor)

        # Try starting from each city
        for start in range(n):
            visited = {start}
            dfs(start, visited, 0, 0)

        return max_cost

