class Solution:
    def maximumCost(self, n: int, highways: List[List[int]], k: int) -> int:
        from collections import defaultdict

        # Build adjacency list
        graph = defaultdict(list)
        for city1, city2, toll in highways:
            graph[city1].append((city2, toll))
            graph[city2].append((city1, toll))

        max_cost = -1

        # We need a path of exactly k edges (highways), visiting k+1 distinct cities.
        # Since n can be up to 50 and k up to 49, brute force permutations is O(n!/(n-k-1)!), which is too slow.
        # We use DFS with memoization or simple backtracking since k is small relative to n but the state space is manageable with pruning.
        # However, given constraints (n <= 50, k <= 49), a full permutation approach is TLE.
        # We must use DFS/backtracking to explore paths of length k.

        # Use DFS to find all paths of length k with distinct nodes
        def dfs(current_city, visited, steps, current_cost):
            nonlocal max_cost
            if steps == k:
                if current_cost > max_cost:
                    max_cost = current_cost
                return

            for neighbor, cost in graph[current_city]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    dfs(neighbor, visited, steps + 1, current_cost + cost)
                    visited.remove(neighbor)

        # Try starting from each city
        for start in range(n):
            visited = {start}
            dfs(start, visited, 0, 0)

        return max_cost

