        # Replacing a digit 'd' (where d != '0') with '0' minimizes the number.
        # However, we cannot simply replace any non-zero digit; we must pick the FIRST one encountered 
        # to ensure the most significant change. Also, replacing a digit that appears later won't help as much.
        # The logic holds: find the first digit that is not '0', and replace ALL its occurrences with '0'.
        for d in num_str:
            if d != '0':
                min_val = int(num_str.replace(d, '0'))
                break
        else:
            min_val = num  # All digits are 0

        return max_val - min_val

