class Solution:
    def minScoreTriangulation(self, values: List[int]) -> int:
        n = len(values)
        # Initialize a 2D DP table
        dp = [[0] * n for _ in range(n)]

        # Length of the polygon segment (distance between i and j)
        # We start with length 2 because we need at least 3 points to form a triangle (i, k, j where j = i + l)
        for l in range(2, n):
            for i in range(n - l):
                j = i + l
                dp[i][j] = float('inf')
                for k in range(i + 1, j):
                    # Triangle formed by vertices i, k, j
                    score = dp[i][k] + dp[k][j] + values[i] * values[k] * values[j]
                    dp[i][j] = min(dp[i][j], score)

        return dp[0][n - 1]

