class Solution:
    def killProcess(self, pid: List[int], ppid: List[int], kill: int) -> List[int]:
        from collections import defaultdict, deque

        # Build the tree using a dictionary where key is parent and value is list of children
        tree = defaultdict(list)
        for child, parent in zip(pid, ppid):
            tree[parent].append(child)

        # BFS to collect all processes that will be killed starting from 'kill'
        result = []
        queue = deque([kill])

        while queue:
            current = queue.popleft()
            result.append(current)
            for child in tree[current]:
                queue.append(child)

        return result

class Solution:
    def simulationResult(self, windows: List[int], queries: List[int]) -> List[int]:
        result = []
        seen = set()

        # Process queries first to determine the order of recently accessed windows
        for q in queries:
            if q not in seen:
                result.append(q)
                seen.add(q)

        # Append remaining windows that were never queried, preserving their original relative order
        for w in windows:
            if w not in seen:
                result.append(w)

        return result

