class Solution:
    def minArea(self, image: List[List[str]], x: int, y: int) -> int:
        m, n = len(image), len(image[0])

        def has_black_in_col(left, right):
            for c in range(left, right + 1):
                for r in range(m):
                    if image[r][c] == '1':
                        return True
            return False

        def has_black_in_row(top, bottom):
            for r in range(top, bottom + 1):
                for c in range(n):
                    if image[r][c] == '1':
                        return True
            return False

        # Find top boundary (smallest row index with a black pixel)
        low, high = 0, x
        while low < high:
            mid = (low + high) // 2
            if has_black_in_row(mid, x):
                high = mid
            else:
                low = mid + 1
        top = low

        # Find bottom boundary (largest row index with a black pixel)
        low, high = x, m - 1
        while low < high:
            mid = (low + high + 1) // 2
            if has_black_in_row(x, mid):
                low = mid
            else:
                high = mid - 1
        bottom = low

        # Find left boundary (smallest column index with a black pixel)
        low, high = 0, y
        while low < high:
            mid = (low + high) // 2
            if has_black_in_col(mid, y):
                high = mid
            else:
                low = mid + 1
        left = low

        # Find right boundary (largest column index with a black pixel)
        low, high = y, n - 1
        while low < high:
            mid = (low + high + 1) // 2
            if has_black_in_col(y, mid):
                low = mid
            else:
                high = mid - 1
        right = low

        return (bottom - top + 1) * (right - left + 1)

