                    if image[r][c] == '1':
                        return True
            return False

        # Find top boundary
        low, high = 0, x
        while low < high:
            mid = (low + high) // 2
            if has_black_in_row(mid, x):
                high = mid
            else:
                low = mid + 1
        top = low

        # Find bottom boundary
        low, high = x, m - 1
        while low < high:
            mid = (low + high + 1) // 2
            if has_black_in_row(x, mid):
                low = mid
            else:
                high = mid - 1
        bottom = low

        # Find left boundary
        low, high = 0, y
        while low < high:
            mid = (low + high) // 2
            if has_black_in_col(mid, y):
                high = mid
            else:
                low = mid + 1
        left = low

        # Find right boundary
        low, high = y, n - 1
        while low < high:
            mid = (low + high + 1) // 2
            if has_black_in_col(y, mid):
                low = mid
            else:
                high = mid - 1
        right = low

        return (bottom - top + 1) * (right - left + 1)

