class Solution:
    def minArea(self, image: List[List[str]], x: int, y: int) -> int:
        from typing import List

        m, n = len(image), len(image[0])

        def is_black(row, col):
            return image[row][col] == '1'

        def has_black_in_col(left, right, is_row_search):
            if is_row_search:
                for r in range(left, right + 1):
                    for c in range(n):
                        if is_black(r, c):
                            return True
            else:
                for c in range(left, right + 1):
                    for r in range(m):
                        if is_black(r, c):
                            return True
            return False

        def binary_search(start, end, is_row_search):
            while start < end:
                mid = (start + end) // 2
                if has_black_in_col(start, mid, is_row_search):
                    end = mid
                else:
                    start = mid + 1
            return start

        top = binary_search(0, x, True)
        bottom = binary_search(x, m - 1, True)
        left = binary_search(0, y, False)
        right = binary_search(y, n - 1, False)

        return (bottom - top) * (right - left)

