```python
class Solution:
    def findRelativeRanks(self, score: List[int]) -> List[str]:
        # Create a sorted list of scores in descending order
        sorted_scores = sorted(score, reverse=True)

        # Map each score to its rank (position in the sorted list + 1)
        rank_map = {}
        for i, s in enumerate(sorted_scores):
            rank = i + 1
            if rank == 1:
                rank_map[s] = "Gold Medal"
            elif rank == 2:
                rank_map[s] = "Silver Medal"
            elif rank == 3:
                rank_map[s] = "Bronze Medal"
            else:
                rank_map[s] = str(rank)

        # Build the result by looking up each score's rank
        return [rank_map[s] for s in score]
```

