class Solution:
    def getMaxGridHappiness(self, m: int, n: int, introvertsCount: int, extrovertsCount: int) -> int:
        from functools import lru_cache

        # Happiness constants
        INTRO_HAPPINESS = 120
        EXTRO_HAPPINESS = 40
        INTRO_NEIGHBOR_PENALTY = -30
        EXTRO_NEIGHBOR_BONUS = +20

        total_cells = m * n

        @lru_cache(None)
        def dp(pos, prev_row_state, ic, ec):
            if pos == total_cells or (ic == 0 and ec == 0):
                return 0

            row = pos // n
            col = pos % n

            # Calculate happiness changes due to neighbors in the same row
            left_neighbor = (prev_row_state >> (col * 2)) & 3
            top_neighbor = (prev_row_state >> ((col + 1) * 2)) & 3 if row > 0 else 0

            max_happiness = 0

            # Case 1: Place nothing
            next_pos = pos + 1
            next_prev_row_state = (prev_row_state << 2) | 0
            if col == n - 1:
                next_prev_row_state >>= 2 * n
            max_happiness = max(max_happiness, dp(next_pos, next_prev_row_state, ic, ec))

            # Case 2: Place an introvert
            if ic > 0:
                new_happiness = INTRO_HAPPINESS
                if left_neighbor != 0:
                    new_happiness += INTRO_NEIGHBOR_PENALTY if left_neighbor == 1 else INTRO_NEIGHBOR_PENALTY
                    new_happiness += EXTRO_NEIGHBOR_BONUS if left_neighbor == 2 else 0
                if top_neighbor != 0:
                    new_happiness += INTRO_NEIGHBOR_PENALTY if top_neighbor == 1 else INTRO_NEIGHBOR_PENALTY
                    new_happiness += EXTRO_NEIGHBOR_BONUS if top_neighbor == 2 else 0

                if left_neighbor == 1:
                    new_happiness += INTRO_NEIGHBOR_PENALTY
                elif left_neighbor == 2:
                    new_happiness += EXTRO_NEIGHBOR_BONUS

                if top_neighbor == 1:
                    new_happiness += INTRO_NEIGHBOR_PENALTY
                elif top_neighbor == 2:
                    new_happiness += EXTRO_NEIGHBOR_BONUS

                next_prev_row_state = (prev_row_state << 2) | 1
                if col == n - 1:
                    next_prev_row_state >>= 2 * n
                max_happiness = max(max_happiness, new_happiness + dp(next_pos, next_prev_row_state, ic - 1, ec))

            # Case 3: Place an extrovert
            if ec > 0:
                new_happiness = EXTRO_HAPPINESS
                if left_neighbor != 0:
                    new_happiness += EXTRO_NEIGHBOR_BONUS if left_neighbor == 1 else EXTRO_NEIGHBOR_BONUS
                    new_happiness += EXTRO_NEIGHBOR_BONUS if left_neighbor == 2 else 0
                if top_neighbor != 0:
                    new_happiness += EXTRO_NEIGHBOR_BONUS if top_neighbor == 1 else EXTRO_NEIGHBOR_BONUS
                    new_happiness += EXTRO_NEIGHBOR_BONUS if top_neighbor == 2 else 0

                if left_neighbor == 1:
                    new_happiness += EXTRO_NEIGHBOR_BONUS
                elif left_neighbor == 2:
                    new_happiness += EXTRO_NEIGHBOR_BONUS

                if top_neighbor == 1:
                    new_happiness += EXTRO_NEIGHBOR_BONUS
                elif top_neighbor == 2:
                    new_happiness += EXTRO_NEIGHBOR_BONUS

                next_prev_row_state = (prev_row_state << 2) | 2
                if col == n - 1:
                    next_prev_row_state >>= 2 * n
                max_happiness = max(max_happiness, new_happiness + dp(next_pos, next_prev_row_state, ic, ec - 1))

            return max_happiness

        return dp(0, 0, introvertsCount, extrovertsCount)
