class Solution:
    def countNumbersWithUniqueDigits(self, n: int) -> int:
        if n == 0:
            return 1

        unique_count = 10  # All 1-digit numbers are unique (including 0)
        available_digits = 9  # First digit has 9 options (1-9)

        for i in range(2, n + 1):
            available_digits *= (11 - i)  # Remaining digits have decreasing choices
            unique_count += available_digits

        return unique_count
