# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, x):
#         self.val = x
#         self.left = None
#         self.right = None

class Solution:
    def lowestCommonAncestor(self, root: 'TreeNode', p: 'TreeNode', q: 'TreeNode') -> 'TreeNode':
        def dfs(node):
            if not node:
                return None

            # If current node is one of p or q, return it
            if node == p or node == q:
                return node

            left = dfs(node.left)
            right = dfs(node.right)

            # If both left and right are not None, then current node is LCA
            if left and right:
                return node

            # Otherwise, return the non-null child (either left or right)
            return left if left else right

        lca = dfs(root)

        # Verify that both p and q exist in the tree by checking if they were used in the traversal
        # We can do this by doing a second traversal to check existence
        def exists(node, target):
            if not node:
                return False
            if node == target:
                return True
            return exists(node.left, target) or exists(node.right, target)

        if exists(root, p) and exists(root, q):
            return lca
        else:
            return None

