class Solution:
    def checkIfPangram(self, sentence: str) -> bool:
        if len(sentence) < 26:
            return False
        seen = set()
        for char in sentence:
            if 'a' <= char <= 'z':
                seen.add(char)
                if len(seen) == 26:
                    return True
        return False

