class Solution:
    def beautifulIndices(self, s: str, a: str, b: str, k: int) -> List[int]:
        def find_all_indices(text: str, pattern: str) -> List[int]:
            res = []
            n = len(pattern)
            if n > len(text):
                return res
            for i in range(len(text) - n + 1):
                if text[i:i+n] == pattern:
                    res.append(i)
            return res

        a_indices = find_all_indices(s, a)
        b_indices = find_all_indices(s, b)

        # Sort and prepare for binary search (though find_all_indices returns sorted by nature of iteration)
        b_indices.sort()

        result = []
        from bisect import bisect_left, bisect_right

        for i in a_indices:
            # Find the first b index >= i - k
            left = bisect_left(b_indices, i - k)
            # Check if any of the next few b indices are within [i - k, i + k]
            # We only need to check if there is at least one valid b_index
            if left < len(b_indices) and b_indices[left] <= i + k:
                result.append(i)

        return result

