# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def countPairs(self, root: Optional[TreeNode], distance: int) -> int:
        self.good_pairs = 0

        def dfs(node):
            if not node:
                return []
            if not node.left and not node.right:
                return [1]  # Distance from this leaf to itself is 1 (depth)

            left_distances = dfs(node.left)
            right_distances = dfs(node.right)

            # Count good pairs between leaves in left and right subtrees
            for l in left_distances:
                for r in right_distances:
                    if l + r <= distance:
                        self.good_pairs += 1

            # Add 1 to all distances to propagate up one level
            return [d + 1 for d in left_distances] + [d + 1 for d in right_distances]

        dfs(root)
        return self.good_pairs
```

