            for l in left_distances:
                for r in right_distances:
                    if l + r <= distance:
                        self.good_pairs += 1

            # Add 1 to all distances to propagate up one level
            new_distances = [d + 1 for d in left_distances] + [d + 1 for d in right_distances]

            # Filter out distances that are already greater than or equal to distance
            # because they can never form a valid pair with any other node further up
            return [d for d in new_distances if d < distance]

        dfs(root)
        return self.good_pairs

