class Solution:
    def lengthLongestPath(self, input: str) -> int:
        max_len = 0
        path_len = {0: 0}  # depth: current path length up to this depth

        for line in input.split('\n'):
            name = line.lstrip('\t')
            depth = len(line) - len(name)

            if '.' in name:
                # It's a file, update max_len
                max_len = max(max_len, path_len[depth] + len(name))
            else:
                # It's a directory, update the path length for the next depth
                path_len[depth + 1] = path_len[depth] + len(name) + 1  # add 1 for the '/'

        return max_len

class Solution:
    def shortestAlternatingPaths(self, n: int, redEdges: List[List[int]], blueEdges: List[List[int]]) -> List[int]:
        from collections import deque, defaultdict

        # Build adjacency list for both colors
        graph = [defaultdict(list) for _ in range(n)]
        for a, b in redEdges:
            graph[a].append(('blue', b))
        for u, v in blueEdges:
            graph[u].append(('red', v))

        # Initialize answer array with -1
        answer = [-1] * n
        visited = [[False] * 2 for _ in range(n)]  # visited[node][color], color: 0 for red, 1 for blue

        # BFS queue: (node, next_color, distance)
        # Start at node 0 with no color (can start with either red or blue edge)
        queue = deque()
        queue.append((0, 'blue', 0))
        queue.append((0, 'red', 0))

        while queue:
            node, color, dist = queue.popleft()

            if visited[node][0 if color == 'red' else 1]:
                continue

            visited[node][0 if color == 'red' else 1] = True
            if answer[node] == -1:
                answer[node] = dist

            # Traverse the opposite color edges
            for next_color, next_node in graph[node]:
                if not visited[next_node][0 if next_color == 'red' else 1]:
                    queue.append((next_node, next_color, dist + 1))

        return answer

