class Solution:
    def idealArrays(self, n: int, maxValue: int) -> int:
        MOD = 10**9 + 7

        # Precompute factorials and inverse factorials up to maxValue
        max_val = maxValue
        fact = [1] * (max_val + 1)
        inv_fact = [1] * (max_val + 1)

        for i in range(1, max_val + 1):
            fact[i] = fact[i - 1] * i % MOD

        # Fermat's little theorem for modular inverse
        inv_fact[max_val] = pow(fact[max_val], MOD - 2, MOD)
        for i in range(max_val - 1, 0, -1):
            inv_fact[i] = inv_fact[i + 1] * (i + 1) % MOD

        def comb(a, b):
            if a < b or b < 0:
                return 0
            return fact[a] * inv_fact[b] % MOD * inv_fact[a - b] % MOD

        from collections import defaultdict

        # Count divisors for each number up to maxValue
        div_count = [0] * (maxValue + 1)
        for i in range(1, maxValue + 1):
            for j in range(i, maxValue + 1, i):
                div_count[j] += 1

        result = 0
        for v in range(1, maxValue + 1):
            k = div_count[v]
            result = (result + comb(n - 1, k - 1)) % MOD

        return result
```

