class Solution:
    def hardestWorker(self, n: int, logs: List[List[int]]) -> int:
        max_time = 0
        longest_id = logs[0][0]
        prev_time = 0

        for i in range(len(logs)):
            id_, end_time = logs[i]
            duration = end_time - prev_time
            if duration > max_time:
                max_time = duration
                longest_id = id_
            elif duration == max_time and id_ < longest_id:
                longest_id = id_
            prev_time = end_time

        return longest_id

