class Solution:
    def ways(self, pizza: List[str], k: int) -> int:
        from functools import lru_cache

        MOD = 10**9 + 7
        rows, cols = len(pizza), len(pizza[0])

        # Precompute the number of apples in each submatrix (suffix sum)
        # suffix_apple[r][c] stores the count of 'A's in the rectangle from (r, c) to (rows-1, cols-1)
        suffix_apple = [[0] * (cols + 1) for _ in range(rows + 1)]
        for r in reversed(range(rows)):
            for c in reversed(range(cols)):
                suffix_apple[r][c] = (1 if pizza[r][c] == 'A' else 0) + \
                                     suffix_apple[r+1][c] + \
                                     suffix_apple[r][c+1] - \
                                     suffix_apple[r+1][c+1]

        @lru_cache(None)
        def dp(r, c, k_left):
            # If no more cuts needed, we just need to check if the current piece has an apple
            if k_left == 0:
                return 1 if suffix_apple[r][c] > 0 else 0

            res = 0

            # Try cutting horizontally
            # We cut at row nr, meaning the top piece is from r to nr-1, and the remaining is from nr to end
            # The condition is that the top piece must have at least one apple.
            # The top piece apples = total(r,c) - total(nr,c)
            for nr in range(r + 1, rows):
                # Apples in the top part (given away)
                top_apples = suffix_apple[r][c] - suffix_apple[nr][c]
                if top_apples > 0:
                    res = (res + dp(nr, c, k_left - 1)) % MOD

            # Try cutting vertically
            # We cut at col nc, meaning the left piece is from c to nc-1, and the remaining is from nc to end
            for nc in range(c + 1, cols):
                # Apples in the left part (given away)
                left_apples = suffix_apple[r][c] - suffix_apple[r][nc]
                if left_apples > 0:
                    res = (res + dp(r, nc, k_left - 1)) % MOD

            return res

        return dp(0, 0, k - 1)

