class Solution:
    def ways(self, pizza: List[str], k: int) -> int:
        from functools import lru_cache

        MOD = 10**9 + 7
        rows, cols = len(pizza), len(pizza[0])

        # Precompute the number of apples in each submatrix (suffix sum)
        suffix = [[0] * (cols + 1) for _ in range(rows + 1)]
        for r in reversed(range(rows)):
            for c in reversed(range(cols)):
                suffix[r][c] = (pizza[r][c] == 'A') + suffix[r+1][c] + suffix[r][c+1] - suffix[r+1][c+1]

        # Check if a submatrix from (r,c) to bottom-right has at least one apple
        def has_apple(r, c):
            return suffix[r][c] > 0

        @lru_cache(None)
        def dp(r, c, cuts_left):
            if cuts_left == 0:
                return 1 if has_apple(r, c) else 0

            res = 0

            # Try cutting horizontally: split into top part [r, nr-1] and bottom part [nr, ...]
            # Top part must have apple, bottom part (remaining) must have apple
            for nr in range(r + 1, rows):
                # Apples in top part: suffix[r][c] - suffix[nr][c]
                apples_top = suffix[r][c] - suffix[nr][c]
                # Apples in bottom part (remaining): suffix[nr][c]
                apples_bottom = suffix[nr][c]

                if apples_top > 0 and apples_bottom > 0:
                    res = (res + dp(nr, c, cuts_left - 1)) % MOD

            # Try cutting vertically: split into left part [c, nc-1] and right part [nc, ...]
            # Left part must have apple, right part (remaining) must have apple
            for nc in range(c + 1, cols):
                # Apples in left part: suffix[r][c] - suffix[r][nc]
                apples_left = suffix[r][c] - suffix[r][nc]
                # Apples in right part (remaining): suffix[r][nc]
                apples_right = suffix[r][nc]

                if apples_left > 0 and apples_right > 0:
                    res = (res + dp(r, nc, cuts_left - 1)) % MOD

            return res

        return dp(0, 0, k - 1)

