        @lru_cache(None)
        def dp(r, c, k_left):
            # If no cuts left, we must have at least one apple in the current piece
            if k_left == 0:
                return 1 if suffix_apple[r][c] > 0 else 0

            res = 0

            # Try cutting horizontally: cut after row nr (nr ranges from r+1 to rows-1)
            # The top piece is (r, c) to (nr-1, cols-1). It must have an apple.
