class Solution:
    def ways(self, pizza: List[str], k: int) -> int:
        from functools import lru_cache

        MOD = 10**9 + 7
        rows, cols = len(pizza), len(pizza[0])

        # Precompute the number of apples in each submatrix (suffix sum)
        # prefix[r][c] stores the number of apples in the rectangle from (r, c) to (rows-1, cols-1)
        suffix_apples = [[0] * (cols + 1) for _ in range(rows + 1)]
        for r in reversed(range(rows)):
            for c in reversed(range(cols)):
                suffix_apples[r][c] = (1 if pizza[r][c] == 'A' else 0) + suffix_apples[r+1][c] + suffix_apples[r][c+1] - suffix_apples[r+1][c+1]

        # Check if a submatrix from (r,c) to bottom-right has at least one apple
        def has_apple(r, c):
            return suffix_apples[r][c] > 0

        @lru_cache(None)
        def dp(r, c, k_left):
            # If we have 1 piece left to cut (k_left=1), we just need to check if the current remaining part has an apple
            if k_left == 1:
                return 1 if has_apple(r, c) else 0

            res = 0

            # Try cutting horizontally
            # Cut after row nr (0-indexed), so the top piece is rows r to nr-1, and the bottom piece starts at nr
            # The top piece must have an apple. The bottom piece (starting at nr, c) will be processed in the next step.
            for nr in range(r + 1, rows):
                # Check if the top piece (from r to nr-1) has at least one apple
                # Top piece apples = total from (r,c) minus total from (nr, c)
                top_apples = suffix_apples[r][c] - suffix_apples[nr][c]
                if top_apples > 0:
                    res = (res + dp(nr, c, k_left - 1)) % MOD

            # Try cutting vertically
            # Cut after col nc (0-indexed), so the left piece is cols c to nc-1, and the right piece starts at nc
            for nc in range(c + 1, cols):
                # Check if the left piece (from c to nc-1) has at least one apple
                # Left piece apples = total from (r,c) minus total from (r, nc)
                left_apples = suffix_apples[r][c] - suffix_apples[r][nc]
                if left_apples > 0:
                    res = (res + dp(r, nc, k_left - 1)) % MOD

            return res

        # We need to make k pieces, which means k-1 cuts.
        # However, the problem says "slice into k pieces using exactly k-1 cuts".
        # The state k_left represents the number of pieces we still need to form from the current sub-pizza.
        # Initially, we want to form k pieces.
        # When k_left becomes 1, it means the current remaining piece is the last one, so we just verify it has an apple.

        return dp(0, 0, k)

