class Solution:
    def checkWays(self, pairs: List[List[int]]) -> int:
        from collections import defaultdict

        # Build the adjacency list and frequency map
        graph = defaultdict(set)
        for u, v in pairs:
            graph[u].add(v)
            graph[v].add(u)

        n = len(graph)
        root = None

        # Find the root node (it must be connected to all other nodes)
        for node in graph:
            if len(graph[node]) == n - 1:
                root = node
                break
        if root is None:
            return 0  # No valid root found

        res = 1
        for node in graph:
            if node == root:
                continue
            curr_neighbors = graph[node]
            parent = None
            min_degree = float('inf')

            # Find a potential parent for this node
            for neighbor in curr_neighbors:
                if len(graph[neighbor]) < min_degree and neighbor != node:
                    parent = neighbor
                    min_degree = len(graph[neighbor])

            if parent is None or not curr_neighbors.issubset(graph[parent]):
                return 0  # Invalid tree structure

            if len(graph[parent]) == len(curr_neighbors):
                res = 2  # Multiple ways to construct the tree

        return res

