from typing import List

class Solution:
    def countMatchingSubarrays(self, nums: List[int], pattern: List[int]) -> int:
        m = len(pattern)
        n = len(nums)
        result = 0

        # Precompute the comparison pattern of nums
        # Convert nums into a difference array based on comparison with next element
        comp = []
        for i in range(n - 1):
            if nums[i + 1] > nums[i]:
                comp.append(1)
            elif nums[i + 1] == nums[i]:
                comp.append(0)
            else:
                comp.append(-1)

        # Now check each subarray of length m in comp to match pattern
        for i in range(len(comp) - m + 1):
            if comp[i:i + m] == pattern:
                result += 1

        return result
