from typing import List

class Solution:
    def countMatchingSubarrays(self, nums: List[int], pattern: List[int]) -> int:
        m = len(pattern)
        n = len(nums)

        if m + 1 > n:
            return 0

        result = 0

        # Precompute the comparison pattern of nums
        comp = []
        for i in range(n - 1):
            if nums[i + 1] > nums[i]:
                comp.append(1)
            elif nums[i + 1] == nums[i]:
                comp.append(0)
            else:
                comp.append(-1)

        # Check each subarray of length m in comp to match pattern
        for i in range(len(comp) - m + 1):
            match = True
            for k in range(m):
                if comp[i + k] != pattern[k]:
                    match = False
                    break
            if match:
                result += 1

        return result

