class Solution:
    def minSumOfLengths(self, arr: List[int], target: int) -> int:
        n = len(arr)
        prefix_sum = 0
        sum_indices = {0: -1}
        min_len_first = [float('inf')] * n
        best_len = float('inf')

        # First pass: find best subarray before index i with sum == target
        for i in range(n):
            prefix_sum += arr[i]
            if (prefix_sum - target) in sum_indices:
                length = i - sum_indices[prefix_sum - target]
                best_len = min(best_len, length)
            min_len_first[i] = best_len
            sum_indices[prefix_sum] = i

        res = float('inf')
        best_len = float('inf')
        sum_indices = {0: n}
        prefix_sum = 0

        # Second pass: find best subarray after index i and combine with first part
        for i in range(n - 1, -1, -1):
            prefix_sum += arr[i]
            if (prefix_sum + target) in sum_indices:
                length = sum_indices[prefix_sum + target] - i
                if min_len_first[i - 1] != float('inf'):
                    res = min(res, length + min_len_first[i - 1])
            sum_indices[prefix_sum] = i

        return res if res != float('inf') else -1

