class Solution:
    def makeIntegerBeautiful(self, n: int, target: int) -> int:
        def digit_sum(x: int) -> int:
            return sum(int(d) for d in str(x))

        x = 0
        i = 1
        while digit_sum(n + x) > target:
            # Round up to the next number with trailing zeros (e.g., 16 -> 20, 467 -> 500)
            m = (n + x) // (10 ** i) * (10 ** i)
            next_rounded = ((n + x) // (10 ** i) + 1) * (10 ** i)
            x += next_rounded - (n + x)
            i += 1

        return x
