class Solution:
    def uniquePathsIII(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])
        start_x = start_y = end_x = end_y = 0
        empty = 1  # Start and end count as empty squares too

        for i in range(m):
            for j in range(n):
                if grid[i][j] == 1:
                    start_x, start_y = i, j
                elif grid[i][j] == 2:
                    end_x, end_y = i, j
                if grid[i][j] in (0, 1, 2):
                    empty += 1

        directions = [(-1,0), (1,0), (0,-1), (0,1)]
        self.result = 0

        def dfs(x, y, steps):
            if grid[x][y] == 2:
                if steps == empty:
                    self.result += 1
                return
            temp = grid[x][y]
            grid[x][y] = -1
            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if 0 <= nx < m and 0 <= ny < n and grid[nx][ny] != -1:
                    dfs(nx, ny, steps + 1)
            grid[x][y] = temp

        dfs(start_x, start_y, 1)
        return self.result
