class Solution:
    def uniquePathsIII(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])
        start_x = start_y = 0
        empty_count = 0

        for i in range(m):
            for j in range(n):
                if grid[i][j] == 1:
                    start_x, start_y = i, j
                elif grid[i][j] == 2:
                    pass # End square
                elif grid[i][j] == 0:
                    empty_count += 1

        # We need to visit all 0s + the end square (which is visited at the very end)
        # The path length should be equal to number of 0s + 1 (for the end square)
        # But wait, the problem says "walk over every non-obstacle square exactly once".
        # Non-obstacle squares are 0, 1, and 2.
        # So total steps needed = count(0) + 1 (start) + 1 (end) - 1 (since we start at start, we don't "walk over" it again? No.)
        # Let's re-read carefully: "walk over every non-obstacle square exactly once".
        # This includes start, end, and all 0s.
        # Total non-obstacle squares = count(0) + 2 (start and end).
        # In DFS, 'steps' usually counts how many cells we have visited so far.
        # If we start at start (step 1), then we need to reach step = total_non_obstacles when we hit 2.

        total_non_obstacles = empty_count + 2 
        directions = [(-1,0), (1,0), (0,-1), (0,1)]
        self.result = 0

        def dfs(x, y, steps):
            if grid[x][y] == 2:
                if steps == total_non_obstacles:
                    self.result += 1
                return

            temp = grid[x][y]
