        s = s.replace(' ', '')  # Remove all spaces
        stack = []
        num = 0
        sign = '+'

        for i in range(len(s)):
            if s[i].isdigit():
                num = num * 10 + int(s[i])

            # If current char is an operator or it's the last character, process the previous number
            if (not s[i].isdigit()) or i == len(s) - 1:
                if sign == '+':
                    stack.append(num)
                elif sign == '-':
                    stack.append(-num)
                elif sign == '*':
                    stack.append(stack.pop() * num)
                elif sign == '/':
                    prev = stack.pop()
                    # Integer division truncates toward zero.
                    # In Python, // truncates toward negative infinity, so we need to handle negatives carefully.
                    # For positive numbers, prev // num works as expected.
                    # For negative numbers, int(prev / num) gives the correct truncation toward zero.
                    if prev < 0:
                        stack.append(int(prev / num))
                    else:
                        stack.append(prev // num)

                sign = s[i]
                num = 0

        return sum(stack)

