class Solution:
    def lengthOfLongestSubsequence(self, nums: List[int], target: int) -> int:
        from collections import defaultdict

        # dp[sum] = max_length of subsequence that sums to 'sum'
        dp = {0: 0}

        for num in nums:
            new_dp = dp.copy()
            for s in dp:
                new_sum = s + num
                if new_sum <= target:
                    new_dp[new_sum] = max(new_dp.get(new_sum, 0), dp[s] + 1)
            dp = new_dp

        return dp.get(target, -1)
```

