# Definition for a category handler.
# class CategoryHandler:
#     def haveSameCategory(self, a: int, b: int) -> bool:
#         pass
class Solution:
    def numberOfCategories(self, n: int, categoryHandler: Optional['CategoryHandler']) -> int:
        if n == 0:
            return 0

        parent = list(range(n))

        def find(x):
            root = x
            while parent[root] != root:
                root = parent[root]
            # Path compression
            curr = x
            while curr != root:
                nxt = parent[curr]
                parent[curr] = root
                curr = nxt
            return root

        def union(a, b):
            pa = find(a)
            pb = find(b)
            if pa != pb:
                parent[pb] = pa

        for i in range(1, n):
            if categoryHandler.haveSameCategory(0, i):
                union(0, i)

        unique_categories = set()
        for i in range(n):
            unique_categories.add(find(i))

        return len(unique_categories)

