class Solution:
    def findSmallestRegion(self, regions: List[List[str]], region1: str, region2: str) -> str:
        # Build a parent map to store the parent of each region
        parent = {}

        for region_list in regions:
            parent_of = region_list[0]
            for child in region_list[1:]:
                parent[child] = parent_of

        # Get the path from region1 to the root and store all ancestors including region1 itself
        path = set()
        curr = region1
        while curr is not None:
            path.add(curr)
            if curr in parent:
                curr = parent[curr]
            else:
                break

        # Now traverse from region2 upwards and check if it's in the path
        curr = region2
        while curr not in path:
            if curr in parent:
                curr = parent[curr]
            else:
                # This case should theoretically not happen based on problem guarantees
                return curr

        return curr

