    def findMaxForm(self, strs: List[str], m: int, n: int) -> int:
        # Initialize a 2D DP array where dp[i][j] represents the maximum number of strings
        # that can be included with at most i 0's and j 1's.
        dp = [[0] * (n + 1) for _ in range(m + 1)]

        for s in strs:
            zeros = s.count('0')
            ones = s.count('1')

            # Traverse from m down to zeros and n down to ones to avoid using the same string multiple times
            for i in range(m, zeros - 1, -1):
                for j in range(n, ones - 1, -1):
                    dp[i][j] = max(dp[i][j], dp[i - zeros][j - ones] + 1)

        return dp[m][n]

