class Solution:
    def smallestMissingValueSubtree(self, parents: List[int], nums: List[int]) -> List[int]:
        n = len(parents)
        tree = [[] for _ in range(n)]
        for i in range(1, n):
            tree[parents[i]].append(i)

        ans = [1] * n

        one_index = -1
        for i in range(n):
            if nums[i] == 1:
                one_index = i
                break

        if one_index == -1:
            return ans

        present = set()
        missing = 1

        current = one_index
        while current != -1:
            stack = [current]
            while stack:
                node = stack.pop()
                present.add(nums[node])
                for child in tree[node]:
                    stack.append(child)

            while missing in present:
                missing += 1

            ans[current] = missing
            current = parents[current]

        return ans

