class Solution:
    def canMouseWin(self, grid: List[str], catJump: int, mouseJump: int) -> bool:
        from collections import deque

        rows, cols = len(grid), len(grid[0])
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

        # Find initial positions
        for i in range(rows):
            for j in range(cols):
                if grid[i][j] == 'C':
                    cat_start = (i, j)
                elif grid[i][j] == 'M':
                    mouse_start = (i, j)
                elif grid[i][j] == 'F':
                    food = (i, j)

        max_turns = 1000

        # memo[(mouse_pos, cat_pos, turn)] = result (True if Mouse wins, False otherwise)
        memo = {}

        def get_moves(pos, jump_limit):
            r, c = pos
            moves = []
            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                dist = 0
                while 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] != '#':
                    moves.append((nr, nc))
                    dist += 1
                    if dist >= jump_limit:
                        break
                    nr += dr
                    nc += dc
            moves.append(pos)  # staying in place is allowed
            return list(set(moves))

        def dp(mouse_pos, cat_pos, turn):
            if turn >= max_turns:
                return False  # Cat wins by time limit
            if mouse_pos == food:
                return True  # Mouse wins
            if cat_pos == food:
                return False  # Cat wins
            if mouse_pos == cat_pos:
                return False  # Cat wins

            key = (mouse_pos, cat_pos, turn)
            if key in memo:
                return memo[key]

            is_mouse_turn = (turn % 2 == 0)
            if is_mouse_turn:
                moves = get_moves(mouse_pos, mouseJump)
                can_win = False
                for next_mouse in moves:
                    if dp(next_mouse, cat_pos, turn + 1):
                        can_win = True
                        break
                memo[key] = can_win
                return can_win
            else:
                moves = get_moves(cat_pos, catJump)
                can_lose = False
                for next_cat in moves:
                    if not dp(mouse_pos, next_cat, turn + 1):
                        can_lose = True
                        break
                memo[key] = not can_lose
                return not can_lose

        return dp(mouse_start, cat_start, 0)

