                can_win = False
                for next_mouse in moves:
                    # If the mouse moves to the cat's position, it's a loss immediately? 
                    # No, the rules say "Cat occupies the Mouse's position" -> Cat wins.
                    # If Mouse moves TO Cat, then Cat occupies Mouse's position? 
                    # Actually, the state transition happens after move.
                    # If Mouse moves to Cat's current position, then at end of turn, mouse_pos == cat_pos.
                    # The next call will check mouse_pos == cat_pos and return False.
                    # So we just recurse.
                    if dp(next_mouse, cat_pos, turn + 1):
                        can_win = True
                        break
                memo[key] = can_win
                return can_win
            else:
                moves = get_moves(cat_pos, catJump)
                can_win = True # Assume Cat wins unless Mouse can force a win
