        # State: (mouse_pos, cat_pos, turn)
        # We use BFS/DP with memoization. Since the game is finite and has a limit on turns,
        # we can use minimax with memoization.
        # However, the state space is large (rows*cols * rows*cols * 1000). 
        # But note: the problem asks if Mouse can win assuming optimal play.
        # This is a zero-sum game with perfect information.

        # To avoid TLE and infinite recursion, we rely on the 1000 turn limit.
        # We will use memoization.

        memo = {}

        def get_moves(pos, jump, is_cat):
            r, c = pos
            moves = set()
            moves.add(pos)  # staying in place
