            # If Mouse reaches food, Mouse wins immediately (before Cat's move if it was Mouse's turn)
            # The problem says "Mouse wins if it reaches the food before the Cat"
            # Also "Cat wins if ... reaches the food first".
            # So checking at start of turn:
            if mouse_pos == food:
                return True
            if cat_pos == food:
                return False
            if mouse_pos == cat_pos:
                return False

