            if key in memo:
                return memo[key]

            is_mouse_turn = (turn % 2 == 0)

            if is_mouse_turn:
                moves = get_moves(mouse_pos, mouseJump, False)
                # Mouse wins if there exists a move leading to a winning state
                for next_mouse in moves:
                    if dp(next_mouse, cat_pos, turn + 1):
                        memo[key] = True
                        return True
                memo[key] = False
                return False
            else:
                moves = get_moves(cat_pos, catJump, True)
                # Cat wins if there exists a move leading to a losing state for Mouse (i.e., Cat wins)
                # Cat wants to minimize Mouse's chance. So if ANY move leads to Mouse losing (False), Cat takes it.
                for next_cat in moves:
                    if not dp(mouse_pos, next_cat, turn + 1):
                        memo[key] = False
                        return False
                memo[key] = True
                return True

        return dp(mouse_start, cat_start, 0)

