    def containsNearbyAlmostDuplicate(self, nums: List[int], indexDiff: int, valueDiff: int) -> bool:
        if valueDiff < 0 or indexDiff <= 0:
            return False

        bucket_size = valueDiff + 1
        buckets = {}

        for i in range(len(nums)):
            num = nums[i]
            # Handle negative numbers correctly for bucket ID calculation
            bucket_id = num // bucket_size if num >= 0 else (num + 1) // bucket_size - 1

            if bucket_id in buckets:
                return True

            if (bucket_id - 1) in buckets and abs(num - buckets[bucket_id - 1]) <= valueDiff:
                return True

            if (bucket_id + 1) in buckets and abs(num - buckets[bucket_id + 1]) <= valueDiff:
                return True

            buckets[bucket_id] = num

            if i >= indexDiff:
                remove_num = nums[i - indexDiff]
                remove_bucket_id = remove_num // bucket_size if remove_num >= 0 else (remove_num + 1) // bucket_size - 1
                del buckets[remove_bucket_id]

        return False

