class Solution:
    def isRectangleCover(self, rectangles: List[List[int]]) -> bool:
        corner_points = set()
        area = 0
        min_x = min_y = float('inf')
        max_x = max_y = float('-inf')

        for x1, y1, x2, y2 in rectangles:
            area += (x2 - x1) * (y2 - y1)
            min_x = min(min_x, x1)
            min_y = min(min_y, y1)
            max_x = max(max_x, x2)
            max_y = max(max_y, y2)

            # Define the four corners of the rectangle
            corners = [(x1, y1), (x1, y2), (x2, y1), (x2, y2)]

            for point in corners:
                if point in corner_points:
                    corner_points.remove(point)
                else:
                    corner_points.add(point)

        # The total area should match the area of the bounding rectangle
        expected_area = (max_x - min_x) * (max_y - min_y)

        # There should be exactly 4 corner points left (the corners of the big rectangle)
        return area == expected_area and len(corner_points) == 4 and {
            (min_x, min_y), (min_x, max_y), (max_x, min_y), (max_x, max_y)
        } == corner_points

