class Solution:
    def maxIceCream(self, costs: List[int], coins: int) -> int:
        if not costs:
            return 0

        # Find the maximum cost of an ice cream bar
        max_cost = max(costs)

        # Count sort: count occurrences of each cost
        count = [0] * (max_cost + 1)
        for cost in costs:
            count[cost] += 1

        # Try to buy as many ice creams as possible starting from the cheapest
        total_bars = 0
        for cost in range(1, max_cost + 1):
            if coins < cost:
                break
            num_bars = count[cost]
            if num_bars == 0:
                continue
            max_possible = coins // cost
            bars_to_take = min(num_bars, max_possible)
            total_bars += bars_to_take
            coins -= bars_to_take * cost

        return total_bars

