class Solution:
    def minimumMountainRemovals(self, nums: List[int]) -> int:
        n = len(nums)

        # Longest increasing subsequence from the left
        lis_left = [1] * n
        for i in range(n):
            for j in range(i):
                if nums[j] < nums[i]:
                    lis_left[i] = max(lis_left[i], lis_left[j] + 1)

        # Longest increasing subsequence from the right (which is decreasing from the left)
        lis_right = [1] * n
        for i in range(n - 1, -1, -1):
            for j in range(n - 1, i, -1):
                if nums[j] < nums[i]:
                    lis_right[i] = max(lis_right[i], lis_right[j] + 1)

        # Find the maximum mountain length
        max_mountain = 0
        for i in range(1, n - 1):
            if lis_left[i] >= 2 and lis_right[i] >= 2:
                max_mountain = max(max_mountain, lis_left[i] + lis_right[i] - 1)

        return n - max_mountain

