class Solution:
    def minimumOperations(self, nums: List[int], target: List[int]) -> int:
        operations = 0
        diff = 0

        for n, t in zip(nums, target):
            delta = n - t
            if (delta > 0) == (diff > 0):
                # Same direction, merge the operations
                operations += abs(delta - diff)
            else:
                # Different direction, add new operation
                operations += abs(delta)
            diff = delta

        return operations
```

