class Solution:
    def threeEqualParts(self, arr: List[int]) -> List[int]:
        total_ones = sum(arr)

        # If number of ones is not divisible by 3, it's impossible to split
        if total_ones % 3 != 0:
            return [-1, -1]

        if total_ones == 0:
            return [0, len(arr) - 1]

        k = total_ones // 3
        first_start = -1
        second_start = -1
        third_start = -1
        count = 0

        # Find the start index of each part
        for i, bit in enumerate(arr):
            if bit == 1:
                count += 1
                if count == 1:
                    first_start = i
                elif count == k + 1:
                    second_start = i
                elif count == 2 * k + 1:
                    third_start = i

        # Compare the sequences starting from first_start, second_start and third_start
        n = len(arr)
        while third_start + (first_start - second_start) < n:
            if arr[first_start] != arr[second_start] or arr[first_start] != arr[third_start]:
                return [-1, -1]
            first_start += 1
            second_start += 1
            third_start += 1

        return [first_start - 1, second_start]
