class Solution:
    def threeEqualParts(self, arr: List[int]) -> List[int]:
        total_ones = sum(arr)

        # If number of ones is not divisible by 3, it's impossible to split
        if total_ones % 3 != 0:
            return [-1, -1]

        if total_ones == 0:
            return [0, len(arr) - 1]

        k = total_ones // 3
        first_start = -1
        second_start = -1
        third_start = -1
        count = 0

        # Find the start index of each part
        for i, bit in enumerate(arr):
            if bit == 1:
                count += 1
                if count == 1:
                    first_start = i
                elif count == k + 1:
                    second_start = i
                elif count == 2 * k + 1:
                    third_start = i

        # Compare the sequences starting from first_start, second_start and third_start
        n = len(arr)
        while third_start + (first_start - second_start) < n:
            if arr[first_start] != arr[second_start] or arr[first_start] != arr[third_start]:
                return [-1, -1]
            first_start += 1
            second_start += 1
            third_start += 1

        return [first_start - 1, second_start]

class Solution:
    def findLengthOfShortestSubarray(self, arr: List[int]) -> int:
        n = len(arr)
        left = 0

        # Find the longest non-decreasing prefix
        while left + 1 < n and arr[left] <= arr[left + 1]:
            left += 1

        if left == n - 1:
            return 0  # The whole array is non-decreasing

        right = n - 1

        # Find the longest non-decreasing suffix
        while right - 1 >= 0 and arr[right - 1] <= arr[right]:
            right -= 1

        # Minimum subarray to remove is from left+1 to right-1
        res = min(n - left - 1, right)

        # Try to merge prefix and suffix by removing a middle part
        i = 0
        j = right
        while i <= left and j < n:
            if arr[i] <= arr[j]:
                res = min(res, j - i)
                i += 1
            else:
                j += 1

        return res

