import heapq
from typing import List

class Solution:
    def isPossible(self, target: List[int]) -> bool:
        total = sum(target)
        max_heap = [-x for x in target]
        heapq.heapify(max_heap)

        while -max_heap[0] > 1:
            largest = -heapq.heappop(max_heap)
            rest_sum = total - largest

            if rest_sum == 0 or rest_sum >= largest:
                return False

            new_val = largest % rest_sum
            if new_val < 1:
                new_val = rest_sum

            total = rest_sum + new_val
            heapq.heappush(max_heap, -new_val)

            if -max_heap[0] == 1:
                break

        return True

