class Solution:
    def minimumRefill(self, plants: List[int], capacityA: int, capacityB: int) -> int:
        refill = 0
        left, right = 0, len(plants) - 1
        waterA, waterB = capacityA, capacityB

        while left < right:
            # Alice waters from left
            if waterA < plants[left]:
                waterA = capacityA
                refill += 1
            waterA -= plants[left]
            left += 1

            # Bob waters from right
            if waterB < plants[right]:
                waterB = capacityB
                refill += 1
            waterB -= plants[right]
            right -= 1

        # If they meet at a single plant (odd number of plants)
        if left == right:
            if max(waterA, waterB) < plants[left]:
                refill += 1

        return refill

