class Solution:
    def removeInterval(self, intervals: List[List[int]], toBeRemoved: List[int]) -> List[List[int]]:
        result = []
        rem_start, rem_end = toBeRemoved

        for start, end in intervals:
            # Case 1: interval is completely before or after the toBeRemoved
            if end <= rem_start or start >= rem_end:
                result.append([start, end])
            else:
                # Case 2: left part remains
                if start < rem_start:
                    result.append([start, min(end, rem_start)])
                # Case 3: right part remains
                if end > rem_end:
                    result.append([max(start, rem_end), end])

        return result
