class Solution:
    def maximumLength(self, s: str) -> int:
        from collections import defaultdict

        # Dictionary to store the frequency of each run length for each character
        char_counts = defaultdict(lambda: defaultdict(int))

        n = len(s)
        i = 0
        while i < n:
            j = i
            while j < n and s[j] == s[i]:
                j += 1
            length = j - i
            c = s[i]
            # For a run of length `length`, it contributes substrings of lengths 1 to `length`
            for l in range(1, length + 1):
                char_counts[c][l] += length - l + 1
            i = j

        max_len = -1
        # Check all characters and their substring frequencies
        for c in char_counts:
            for l in sorted(char_counts[c].keys(), reverse=True):
                if char_counts[c][l] >= 3:
                    return l
        return max_len
```

