class Solution:
    def splitLoopedString(self, strs: List[str]) -> str:
        # Preprocess each string to be either itself or its reverse (whichever is lex larger)
        for i in range(len(strs)):
            if strs[i][::-1] > strs[i]:
                strs[i] = strs[i][::-1]

        # Join the modified list into a single looped string
        loop = ''.join(strs)

        # Try cutting at every possible position and check the resulting string
        max_str = loop
        for i in range(len(loop)):
            for s in [loop[i:] + loop[:i], (loop[i:] + loop[:i])[::-1]]:
                if s > max_str:
                    max_str = s

        return max_str
