class Solution:
    def maximumSubtreeSize(self, edges: List[List[int]], colors: List[int]) -> int:
        from collections import defaultdict

        n = len(colors)
        if n == 0:
            return 0

        tree = defaultdict(list)

        # Build the tree as an adjacency list
        for u, v in edges:
            tree[u].append(v)
            tree[v].append(u)

        self.max_size = 1  # At least the root itself is a valid subtree of size 1

        def dfs(node, parent):
            color = colors[node]
            count = 1  # Start with the current node
            is_uniform = True

            for neighbor in tree[node]:
                if neighbor == parent:
                    continue

                child_count = dfs(neighbor, node)

                # If any child subtree is not uniform or has a different color, mark this subtree as invalid
                if child_count == -1 or colors[neighbor] != color:
                    is_uniform = False
                    break

                count += child_count

            if is_uniform:
                self.max_size = max(self.max_size, count)
                return count
            else:
                return -1

        dfs(0, -1)
        return self.max_size

